// Rules data generated by scripts/build-rules.mjs (runs before dev and build).
import rules from '../data/rules.json'

export const { sections, chapters, updated } = rules

export const chapterOrder = sections.flatMap((s) => s.chapters.map((c) => c.id))

export const chapterTitles = Object.fromEntries(chapterOrder.map((id) => [id, chapters[id].title]))

const known = new Set(chapterOrder)
for (const id of chapterOrder) for (const r of chapters[id].rules) known.add(r.id)

export const isKnownRule = (id) => known.has(id)
